import sys
from collections import defaultdict

MOD = 998244353

def main():
    n, m = map(int, sys.stdin.readline().split())
    words = [sys.stdin.readline().strip() for _ in range(n)]

    # Build adjacency list for transitions
    adj = defaultdict(lambda: defaultdict(int))
    for word in words:
        l = len(word)
        if l == 1:
            adj[()][word[0]] += 1
        else:
            for i in range(l):
                prefix = tuple(word[:i])
                suffix = tuple(word[i:])
                adj[prefix][suffix] += 1

    # Get all possible states (prefixes)
    states = set()
    states.add(())
    for word in words:
        for i in range(len(word)):
            states.add(tuple(word[:i]))
    states = list(states)
    state_index = {s: i for i, s in enumerate(states)}
    num_states = len(states)

    # Build transition matrix
    matrix = [[0]*num_states for _ in range(num_states)]
    for i, s in enumerate(states):
        for t, cnt in adj[s].items():
            if t in state_index:
                j = state_index[t]
                matrix[i][j] = cnt

    # Matrix exponentiation
    def mat_mult(a, b):
        res = [[0]*num_states for _ in range(num_states)]
        for i in range(num_states):
            for k in range(num_states):
                if a[i][k] == 0:
                    continue
                for j in range(num_states):
                    res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD
        return res

    def mat_pow(mat, power):
        result = [[0]*num_states for _ in range(num_states)]
        for i in range(num_states):
            result[i][i] = 1
        while power > 0:
            if power % 2 == 1:
                result = mat_mult(result, mat)
            mat = mat_mult(mat, mat)
            power //= 2
        return result

    mat_m = mat_pow(matrix, m)

    # Initial state is empty prefix
    initial = [0]*num_states
    initial[state_index[()]] = 1

    # Compute final counts
    final = [0]*num_states
    for i in range(num_states):
        for j in range(num_states):
            final[j] = (final[j] + initial[i] * mat_m[i][j]) % MOD

    # Sum all possibilities where the final state is empty (suffix is empty)
    total = final[state_index[()]] % MOD
    print(total)

if __name__ == "__main__":
    main()
